package app.noir.mobile;

import android.app.*;
import android.content.*;
import android.os.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Standalone release picker and season review. Only the optional PC destination uses pairing. */
public final class PhoneDownloadsActivity extends PhoneScreen {
    final ExecutorService worker=Executors.newSingleThreadExecutor();JSONObject item,config;boolean season,busy,reachable;String scope="Missing on phone",numbers="1";boolean probing;final List<Row> rows=new ArrayList<>();TextView total;int revision;
    static final class Row {JSONObject item,choice;List<JSONObject> alternatives;boolean selected=true;Row(JSONObject i,List<JSONObject> choices){item=i;alternatives=choices;choice=choices.isEmpty()?null:choices.get(0);selected=choice!=null;}}
    static void open(Context context,JSONObject item,boolean season){context.startActivity(new Intent(context,PhoneDownloadsActivity.class).putExtra("id",item.optString("id")).putExtra("season",season).putExtra("destination","This phone"));}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);item=NoirApp.data.item(getIntent().getStringExtra("id"));if(item==null){finish();return;}season=getIntent().getBooleanExtra("season",false);if(saved!=null){scope=saved.getString("scope",scope);numbers=saved.getString("numbers",numbers);}showForm();if(NoirApp.data.paired())worker.execute(()->{try{NoirApp.data.pcRequest("/v1/pc-downloads",null);reachable=true;runOnUiThread(()->{if(!busy&&rows.isEmpty()&&!isFinishing())showForm();});}catch(Exception ignored){reachable=false;}});}
    @Override protected void onSaveInstanceState(Bundle out){out.putString("scope",scope);out.putString("numbers",numbers);super.onSaveInstanceState(out);}
    void destination(){
        Spinner target=spinner("Destination",reachable?new String[]{"This phone","PC library"}:new String[]{"This phone"},reachable?getIntent().getStringExtra("destination")!=null?getIntent().getStringExtra("destination"):getSharedPreferences("phone-download-ui",0).getString("destination","This phone"):"This phone");
        target.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int position,long id){if(position==0)return;getSharedPreferences("phone-download-ui",0).edit().putString("destination","PC library").apply();sendToPc();}});
    }
    void sendToPc(){if(busy)return;busy=true;feedback.setText("Preparing PC destination…");worker.execute(()->{try{String id=item.optString("pcItemId",item.optString("id"));if(item.optString("id").startsWith("discover-")||item.optString("group").equals("show:"+item.optString("imdb"))){JSONObject payload=new JSONObject();DataStore.put(payload,"id",item.optString("imdb"));DataStore.put(payload,"type",item.optBoolean("movie")?"movie":"series");DataStore.put(payload,"season",item.optInt("season"));DataStore.put(payload,"episode",item.optInt("episode"));id=NoirApp.data.pcRequest("/v1/discover/save",payload).optString("id");}final String pcId=id;runOnUiThread(()->{busy=false;if(!isFinishing()){startActivity(new Intent(this,PcDownloadsActivity.class).putExtra("id",pcId).putExtra("season",season));finish();}});}catch(Exception e){runOnUiThread(()->{busy=false;reachable=false;feedback.setText("PC destination unavailable. Choose This phone to continue.");});}});}
    void showForm(){revision++;page(season?"Season to phone":"Download to phone");destination();body.addView(text(item.optString("title")+" · "+MainActivity.episode(item),18));body.addView(button("Phone download settings",()->startActivity(new Intent(this,PhoneDownloadSettingsActivity.class)),false));
        if(season){List<JSONObject> episodes=NoirApp.data.episodes(item);TreeSet<Integer> seasons=new TreeSet<>();for(JSONObject e:episodes)if(e.optInt("season")>0)seasons.add(e.optInt("season"));if(seasons.isEmpty())seasons.add(item.optInt("season",1));Spinner seasonPicker=spinner("Season",seasons.stream().map(String::valueOf).toArray(String[]::new),Integer.toString(item.optInt("season",1)));Spinner scopePicker=spinner("Episodes",PhoneSeasonPlan.SCOPES,scope);EditText values=input("N, episode numbers (1,3-6), or season numbers for several seasons",numbers,false);values.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){numbers=s.toString();}public void afterTextChanged(android.text.Editable e){}});scopePicker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){scope=scopePicker.getSelectedItem().toString();}});
            body.addView(text("Upcoming episodes are excluded. Saved phone copies are skipped in every scope. Alternatives can be swapped before downloading.",13));body.addView(button("Plan phone downloads",()->{scope=scopePicker.getSelectedItem().toString();numbers=values.getText().toString();Set<String> saved=new HashSet<>();for(JSONObject e:episodes)if(!NoirApp.data.localFile(e.optString("id")).isEmpty())saved.add(e.optString("id"));plan(PhoneSeasonPlan.select(episodes,Integer.parseInt(seasonPicker.getSelectedItem().toString()),scope,numbers,saved,System.currentTimeMillis()));},true));
        }else body.addView(button("Find releases",()->plan(List.of(item)),true));
    }
    void plan(List<JSONObject> episodes){if(busy)return;if((scope.equals("Specific episodes")||scope.equals("Several seasons")||scope.equals("From episode N")||scope.equals("Next N"))&&PhoneSeasonPlan.numbers(numbers).isEmpty()){feedback.setText("Enter episode or season numbers for this scope.");return;}if(episodes.isEmpty()){feedback.setText("No released episodes match this scope.");return;}busy=true;rows.clear();feedback.setText("Finding links on this phone…");int view=revision;worker.execute(()->{try{config=new PhoneDownloadSettings(this).load();PhoneDownloadProvider provider=new PhoneDownloadProvider(config);Map<String,List<JSONObject>> packs=new HashMap<>();int completed=0;for(JSONObject episode:episodes){if(Thread.currentThread().isInterrupted())return;List<JSONObject> choices=new ArrayList<>();String warning="";try{List<JSONObject> found=provider.search(episode);for(JSONObject c:found)if(!c.optBoolean("pack"))choices.add(c);int checked=0;for(JSONObject pack:found)if(pack.optBoolean("pack")&&checked++<6){String key=pack.optString("service")+pack.optString("hash");if(!packs.containsKey(key)){try{packs.put(key,provider.files(pack,episode));}catch(Exception ignored){packs.put(key,List.of());}}}
                    for(List<JSONObject> files:packs.values())for(JSONObject f:files)if(episode.optBoolean("movie")||f.optInt("season")==episode.optInt("season")&&f.optInt("episode")==episode.optInt("episode"))choices.add(f);
                }catch(Exception e){warning="Search unavailable";}
                List<JSONObject> alternatives=PhoneDownloadProvider.ranked(choices,config,"");Row row=new Row(episode,alternatives);rows.add(row);int done=++completed;String note=warning;runOnUiThread(()->{if(view==revision)feedback.setText("Checked "+done+" / "+episodes.size()+" episodes"+(note.isEmpty()?"":" · "+note));});}
                runOnUiThread(()->{busy=false;if(!isFinishing()&&view==revision)review();});
            }catch(Exception e){runOnUiThread(()->{busy=false;if(view==revision)feedback.setText("Couldn't open phone settings or plan downloads. Check the manifest in Download settings.");});}});}
    void review(){revision++;page(season?"Review season download":"Choose a release");destination();body.addView(text("One link per episode · tap a release to swap it. Cloud packs use your phone's saved debrid account.",14));total=text("",15);body.addView(total);
        for(Row row:rows){LinearLayout card=column();card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackground(MainActivity.bg(MainActivity.PANEL,dp(12)));CheckBox check=new CheckBox(this);check.setTextColor(MainActivity.WHITE);check.setText(MainActivity.episode(row.item)+" · "+row.item.optString("episodeTitle",row.item.optString("title")));check.setChecked(row.selected);check.setEnabled(row.choice!=null);check.setOnCheckedChangeListener((v,on)->{row.selected=on;totals();});card.addView(check);Button choice=button(label(row),()->{String[] labels=row.alternatives.stream().map(c->c.optString("name")+" · "+PcDownloadsActivity.size(c.optLong("size"))+" · "+c.optString("service")+(c.optString("fileName").isEmpty()?"":"\n"+c.optString("fileName"))).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Episode alternatives").setItems(labels,(d,n)->{row.choice=row.alternatives.get(n);choiceLabel(row,card);totals();}).setNegativeButton("Cancel",null).show();},false);choice.setEnabled(row.choice!=null);card.addView(choice);body.addView(card);}
        totals();if(reachable)body.addView(button("Add PC / media-server alternatives",this::pcAlternatives,false));body.addView(button("Download",this::enqueue,true));body.addView(button("Change scope / refresh",()->{rows.clear();showForm();},false));feedback.setText(rows.stream().filter(r->r.choice==null).count()+" episodes without a matching link · adjust preferences or retry");}
    void pcAlternatives(){if(busy)return;busy=true;feedback.setText("Checking PC / media-server alternatives…");int view=revision;worker.execute(()->{try{for(Row row:rows){JSONObject response=NoirApp.data.pcRequest("/v1/phone-downloads/search/"+row.item.optString("pcItemId",row.item.optString("id")),null);for(JSONObject c:DataStore.objects(response.optJSONArray("choices"))){DataStore.put(c,"movie",row.item.optBoolean("movie"));if(PhoneDownloadProvider.eligible(c,config))row.alternatives.add(c);}if(row.choice==null&&!row.alternatives.isEmpty()){row.choice=row.alternatives.get(0);row.selected=true;}}runOnUiThread(()->{busy=false;if(view==revision&&!isFinishing())review();});}catch(Exception e){runOnUiThread(()->{busy=false;if(view==revision)feedback.setText("PC alternatives unavailable. Phone links remain ready.");});}});}
    String label(Row row){return row.choice==null?"No link matches phone preferences":row.choice.optString("name")+" · "+PcDownloadsActivity.size(row.choice.optLong("size"))+" · "+row.choice.optString("service");}
    void choiceLabel(Row row,LinearLayout card){((Button)card.getChildAt(1)).setText(label(row));}
    long free(){return new StatFs(NoirApp.downloads.directory.getAbsolutePath()).getAvailableBytes();}
    void totals(){long bytes=0;int count=0,unknown=0;for(Row row:rows)if(row.selected&&row.choice!=null){count++;bytes+=row.choice.optLong("size");if(row.choice.optLong("size")<=0)unknown++;}total.setText(count+" files · "+PcDownloadsActivity.size(bytes)+(unknown>0?" + "+unknown+" unknown sizes":"")+"\n"+PcDownloadsActivity.size(free())+" free on phone · "+PcDownloadsActivity.size(NoirApp.downloads.reservedBytes())+" queued");}
    void enqueue(){long bytes=0;int count=0;for(Row row:rows)if(row.selected&&row.choice!=null){bytes+=row.choice.optLong("size");count++;}if(count==0){feedback.setText("Choose at least one available episode.");return;}if(bytes+NoirApp.downloads.reservedBytes()+32L*1024*1024>free()){feedback.setText("Not enough free phone storage.");return;}try{getSharedPreferences("phone-download-ui",0).edit().putString("destination","This phone").apply();for(Row row:rows)if(row.selected&&row.choice!=null)NoirApp.downloads.enqueuePhone(row.item,row.choice);startForegroundService(new Intent(this,DownloadService.class));startActivity(new Intent(this,DownloadsActivity.class));finish();}catch(Exception e){feedback.setText("Couldn't save the phone queue. Check free storage and try again.");}}
    @Override public void onDestroy(){revision++;worker.shutdownNow();super.onDestroy();}
}
